#ifndef __TBA_DISMOUNT_PROC_ARM_ARMOPERANDCODECA32SIMD_H
#define __TBA_DISMOUNT_PROC_ARM_ARMOPERANDCODECA32SIMD_H

/*
 * ArmOperandCodecA32Simd.h
 *
 * The schemes of the floating point and Advanced SIMD operand kinds of
 * AArch32 (ArmOperandCodecA32Simd.cpp): the m_flags and m_extra values of the
 * specs of gArmA32SimdEncodingTable, which is generated by
 * tests/arm/tools/aarch32_simd.py.
 *
 * Decoded operands:
 *   - the s, d and q registers: KIND_REGISTER (ARM_REG_S0 + n...), a scalar
 *     d0[1] with m_elementIndex
 *   - a list of vector registers (vldm, vld1-4, vtbl): KIND_REGISTER_LIST with
 *     m_optionScheme ARM_A32_OPT_VECTOR_LIST, the first register m_register,
 *     m_count registers m_stride apart; m_elementIndex is the lane ({d0[1]})
 *     and m_isExplicit means all the lanes ({d0[]})
 *   - NEON memory: KIND_MEMORY with the base m_base, the alignment in bits
 *     m_alignment, m_addressing ADDRESSING_PRE_INDEX for the '!' form and
 *     ADDRESSING_POST_INDEX with m_postIndexRegister for the register form
 *   - immediates: KIND_IMMEDIATE, KIND_FLOAT_IMMEDIATE with the text in m_name
 *
 * Author: Elad Raz <e@eladraz.com>
 */
#include "xStl/types.h"
#include "xStl/data/string.h"
#include "dismount/proc/arm/ArmEncodingTable.h"
#include "dismount/proc/arm/ArmOpcode.h"

namespace armdis {

// The m_extra / m_scheme values of the SIMD specs of the kinds ARM_KIND_A32_FIELD,
// ARM_KIND_A32_FIXED and ARM_KIND_A32_OPTION start here (the lower values are
// the ones of ArmOperandCodecA32.h)
enum { ARM_A32_SIMD_BASE = 64 };

// ARM_KIND_A32_MEMORY of the half precision vldr / vstr: [Rn, #+/-imm8 * 2]
enum { ARM_A32_SIMD_ADDR_MODE5_FP16 = ARM_A32_SIMD_BASE };

// The m_flags of ARM_KIND_A32_SREG / DREG / QREG: the shape of the register field
enum ArmA32RegFlags {
    // The field has no top bit: m_extra is not a position (DPR_VFP2: d0-d15)
    ARM_A32_REG_NO_TOP = 0x01,
    // The field is 3 bits wide (DPR_8, SPR_8)
    ARM_A32_REG_BITS3  = 0x02,
    // A scalar register (ARM_KIND_A32_NEON_SCALAR): an s register (SPR_8)
    ARM_A32_REG_SINGLE = 0x04,
    // The register after the one of the fields (vmov s0, s1, r0, r1): +1
    ARM_A32_REG_NEXT   = 0x08
};

// ARM_KIND_A32_NEON_SCALAR: the m_extra, how the index is made
enum ArmA32IndexScheme {
    // 16 bit elements by scalar: bit 5 : bit 3
    ARM_A32_INDEX_M16,
    // 32 bit: bit 5
    ARM_A32_INDEX_M32,
    // vfmal by scalar: bit 3
    ARM_A32_INDEX_S32,
    // The only element (vcmla by a 64 bit scalar)
    ARM_A32_INDEX_ZERO,
    // vdup: bits 19-17, 19-18, 19
    ARM_A32_INDEX_DUP8,
    ARM_A32_INDEX_DUP16,
    ARM_A32_INDEX_DUP32,
    // vmov to / from a core register: bit 21 : bits 6-5, bit 21 : bit 6, bit 21
    ARM_A32_INDEX_MOV8,
    ARM_A32_INDEX_MOV16,
    ARM_A32_INDEX_MOV32
};

// ARM_KIND_A32_FP_LIST: the m_extra
enum ArmA32ListScheme {
    // vldm / vstm / vpush / vpop of s registers: Vd:D, imm8 registers
    ARM_A32_LIST_VFP_S,
    // of d registers: D:Vd, imm8 / 2 registers
    ARM_A32_LIST_VFP_D,
    // fldmx / fstmx: the same as the d registers (imm8 / 2 - the odd form)
    ARM_A32_LIST_VFP_X,
    // vld1-4 / vst1-4 multiple structures: the register count and the
    // spacing come from the type field (bits 11-8) and n from m_flags
    ARM_A32_LIST_STRUCT,
    // single lane: the n in m_flags
    ARM_A32_LIST_LANE,
    // all lanes (vldn dup)
    ARM_A32_LIST_DUP,
    // vtbl / vtbx: the first register at Vn, the count in m_flags
    ARM_A32_LIST_TBL
};

// ARM_KIND_A32_NEON_MEMORY: the m_extra, the alignment rule
enum ArmA32NeonMemoryScheme {
    // The multiple structures: the alignment field at 4 (2 bits)
    ARM_A32_NMEM_STRUCT,
    // The single lane of vld1-4 / vst1-4 and the all lanes: the n in m_flags
    ARM_A32_NMEM_LANE,
    ARM_A32_NMEM_DUP
};

// ARM_KIND_A32_NEON_DATA_TYPE: the m_extra
enum ArmA32DataType {
    // .8 .16 .32 .64 from the size at m_position (2 bits)
    ARM_A32_DTYPE_SIZE
};

// ARM_KIND_A32_FIELD schemes of the SIMD operands
enum ArmA32SimdField {
    // The complex rotation of vcmla: 90 * field at 23 / at 20 (m_position); of
    // vcadd: 90 + 180 * bit 24 (m_position)
    ARM_A32_SIMD_FIELD_ROT = ARM_A32_SIMD_BASE,
    ARM_A32_SIMD_FIELD_ROT_ODD,
    // The modified immediate of vmov / vmvn / vorr / vbic: a at 24, bcd at 16,
    // efgh at 0, cmode at 8, op at 5; printed #0x..., the flags tell the
    // element size: 8, 16, 32 (vmov.i32 and vmvn), the 32 bit with cmode 1111
    // (vmov.f32) and 64
    ARM_A32_SIMD_FIELD_MODIMM,
    ARM_A32_SIMD_FIELD_MODIMM_FLOAT,
    // The immediate of the shifts right: size - field (m_flags the size 8, 16, 32,
    // 64) at 16 (3 to 6 bits)
    ARM_A32_SIMD_FIELD_SHIFT_RIGHT,
    // The immediate of the shifts left: the field at 16, m_flags its width
    ARM_A32_SIMD_FIELD_SHIFT_LEFT,
    // vcvt fixed point of the vfp: 16 or 32 - (imm4:imm1), m_flags 16 / 32
    ARM_A32_SIMD_FIELD_FBITS,
    // vcvt fixed point of NEON: 64 - field (6 bits at 16)
    ARM_A32_SIMD_FIELD_VCVT_IMM,
    // The immediate of vext: the field at m_position, m_flags its width
    ARM_A32_SIMD_FIELD_PLAIN,
    // The floating point immediate of the vfp (imm4H : imm4L): m_flags 16 / 32 / 64
    ARM_A32_SIMD_FIELD_VFP_IMM,
    ARM_A32_SIMD_FIELD_COUNT
};

// ARM_KIND_A32_FIXED texts of the SIMD
enum ArmA32SimdFixed {
    ARM_A32_SIMD_FIXED_FPSCR = ARM_A32_SIMD_BASE,
    ARM_A32_SIMD_FIXED_FPEXC,
    ARM_A32_SIMD_FIXED_FPSID,
    ARM_A32_SIMD_FIXED_MVFR0,
    ARM_A32_SIMD_FIXED_MVFR1,
    ARM_A32_SIMD_FIXED_MVFR2,
    ARM_A32_SIMD_FIXED_FPINST,
    ARM_A32_SIMD_FIXED_FPINST2,
    ARM_A32_SIMD_FIXED_APSR_NZCV,
    ARM_A32_SIMD_FIXED_8,
    ARM_A32_SIMD_FIXED_16,
    ARM_A32_SIMD_FIXED_32,
    ARM_A32_SIMD_FIXED_COUNT
};

// The m_optionScheme of the KIND_REGISTER_LIST of vector registers
enum { ARM_A32_OPT_VECTOR_LIST = 100 };

// The functions of the SIMD codec (ArmOperandCodecA32Simd.cpp)
cString decodeNeonDataType(const ArmOperandSpec& spec, uint32 encoding);
bool encodeNeonDataType(const ArmOperandSpec& spec, cString& suffix, uint32& encoding);
const char* getA32SimdFixedText(uint text);
// The text of an AArch32 SIMD operand (ArmNotationA32Simd.cpp), the kinds that
// the common formatter doesn't know
cString formatSimdOperandA32(const ArmDecodedOperand& operand);

} // namespace armdis

#endif // __TBA_DISMOUNT_PROC_ARM_ARMOPERANDCODECA32SIMD_H
